function spiralTraversal(source, output) {
  const values = [];
  let top = 0;
  let bottom = source.length - 1;
  let left = 0;
  let right = source[0].length - 1;

  while (top <= bottom && left <= right) {
    for (let column = left; column <= right; column++) {
      values.push(source[top][column]);
      output[top][column] = source[top][column];
    }
    top++;

    for (let row = top; row <= bottom; row++) {
      values.push(source[row][right]);
      output[row][right] = source[row][right];
    }
    right--;

    if (top <= bottom) {
      for (let column = right; column >= left; column--) {
        values.push(source[bottom][column]);
        output[bottom][column] = source[bottom][column];
      }
      bottom--;
    }

    if (left <= right) {
      for (let row = bottom; row >= top; row--) {
        values.push(source[row][left]);
        output[row][left] = source[row][left];
      }
      left++;
    }
  }

  return values;
}

