function groupAnagrams(entries, input) {
  const groups = [];

  for (const word of input) {
    const key = [...word].sort().join('');
    let groupIndex = entries.get(key);

    if (groupIndex === undefined) {
      groupIndex = groups.length;
      groups.push([]);
      entries.set(key, groupIndex);
    }

    groups[groupIndex].push(word);
  }

  return groups;
}

